    FString Str(const TSharedPtr<FJsonObject>& O,const TCHAR* K,const FString& D=TEXT("")){ if(!O.IsValid()) return D; FString V; return O->TryGetStringField(K,V)?V:D; }
    int32 Int(const TSharedPtr<FJsonObject>& O,const TCHAR* K,int32 D=0){ if(!O.IsValid()) return D; int32 V=0; return O->TryGetNumberField(K,V)?V:D; }
    float Flt(const TSharedPtr<FJsonObject>& O,const TCHAR* K,float D=0.f){ if(!O.IsValid()) return D; double V=0; return O->TryGetNumberField(K,V)?static_cast<float>(V):D; }
    bool Bool(const TSharedPtr<FJsonObject>& O,const TCHAR* K,bool D=false){ if(!O.IsValid()) return D; bool V=false; return O->TryGetBoolField(K,V)?V:D; }
    TSharedPtr<FJsonObject> Obj(const TSharedPtr<FJsonObject>& O,const TCHAR* K){ const TSharedPtr<FJsonObject>* V=nullptr; return O.IsValid()&&O->TryGetObjectField(K,V)&&V?*V:nullptr; }
    TArray<FString> Strs(const TSharedPtr<FJsonObject>& O,const TCHAR* K){ TArray<FString> R; const TArray<TSharedPtr<FJsonValue>>* A=nullptr; if(O.IsValid()&&O->TryGetArrayField(K,A)&&A){ for(const auto& V:*A){ FString S; if(V.IsValid()&&V->TryGetString(S)) R.Add(S); } } return R; }
    template<typename T,typename F> void ObjArray(const TSharedPtr<FJsonObject>& O,const TCHAR* K,TArray<T>& Out,F Fn){ const TArray<TSharedPtr<FJsonValue>>* A=nullptr; if(O.IsValid()&&O->TryGetArrayField(K,A)&&A){ for(const auto& V:*A){ TSharedPtr<FJsonObject> VO=V.IsValid()?V->AsObject():nullptr; if(VO.IsValid()) Out.Add(Fn(VO)); } } }
    FString AutoPath(const FString& P){ return P+TEXT(".autosave"); }
    FString BakPath(const FString& P,int32 I){ return FString::Printf(TEXT("%s.bak%d"),*P,I); }
    TArray<FString> Candidates(const FString& P,bool PrimaryFirst){ TArray<FString> C; const FString A=AutoPath(P); if(PrimaryFirst){ C={P,A,BakPath(P,1),BakPath(A,1),BakPath(P,2),BakPath(A,2)}; } else { C={A,BakPath(A,1),BakPath(P,1),BakPath(A,2),BakPath(P,2),P}; } return C; }

    bool LoadRoot(const FString& P,TSharedPtr<FJsonObject>& Root,FString& Err)
    {
        FString S; if(!FFileHelper::LoadFileToString(S,*P)){ Err=FString::Printf(TEXT("Could not read save file: %s"),*P); return false; }
        const TSharedRef<TJsonReader<>> R=TJsonReaderFactory<>::Create(S); if(!FJsonSerializer::Deserialize(R,Root)||!Root.IsValid()){ Err=FString::Printf(TEXT("Save file is not valid JSON: %s"),*P); return false; }
        if(!Str(Root,TEXT("mode")).Equals(TEXT("SinglePlayer"),ESearchCase::IgnoreCase)){ Err=FString::Printf(TEXT("Save file is not a single-player save: %s"),*P); return false; }
        if(!Obj(Root,TEXT("currentGameState")).IsValid()&&!Obj(Root,TEXT("initialGameState")).IsValid()){ Err=FString::Printf(TEXT("Save file is missing game state data: %s"),*P); return false; }
        return true;
    }
    bool ValidSave(const FString& P){ if(!FPaths::FileExists(P)) return false; TSharedPtr<FJsonObject> R; FString E; return LoadRoot(P,R,E); }
    bool LoadRootFallback(const FString& P,TSharedPtr<FJsonObject>& R,FString& Err){ TArray<FString> Es; for(const FString& C:Candidates(P,true)){ if(!FPaths::FileExists(C)) continue; FString E; if(LoadRoot(C,R,E)) return true; Es.Add(E); } Err=Es.Num()?FString::Join(Es,TEXT("\n")):FString::Printf(TEXT("No readable save or backup file exists for %s"),*P); return false; }
    bool CopyIfExists(const FString& S,const FString& D,FString& E){ if(!FPaths::FileExists(S)) return true; FString C; if(!FFileHelper::LoadFileToString(C,*S)){ E=FString::Printf(TEXT("Could not read backup source: %s"),*S); return false; } if(!FFileHelper::SaveStringToFile(C,*D)){ E=FString::Printf(TEXT("Could not write backup file: %s"),*D); return false; } return true; }
    bool Rotate(const FString& P,FString& E){ if(!FPaths::FileExists(P)) return true; IFileManager::Get().Delete(*BakPath(P,2),false,true); return CopyIfExists(BakPath(P,1),BakPath(P,2),E)&&CopyIfExists(P,BakPath(P,1),E); }
    bool WriteProtected(const FString& P,const FString& C,bool bRotate,FString& E){ const FString T=P+TEXT(".tmp"); if(!FFileHelper::SaveStringToFile(C,*T)){ E=FString::Printf(TEXT("Could not write temporary save file: %s"),*T); return false; } if(!ValidSave(T)){ IFileManager::Get().Delete(*T,false,true); E=FString::Printf(TEXT("Temporary save failed validation: %s"),*T); return false; } if(bRotate&&!Rotate(P,E)){ IFileManager::Get().Delete(*T,false,true); return false; } if(!FFileHelper::SaveStringToFile(C,*P)){ IFileManager::Get().Delete(*T,false,true); E=FString::Printf(TEXT("Could not write updated save file: %s"),*P); return false; } IFileManager::Get().Delete(*T,false,true); return true; }

