    FDemocracyInvasionRiskState ParseInvasion(const TSharedPtr<FJsonObject>& O){ FDemocracyInvasionRiskState R; R.MilitaryReadinessWarningThreshold=Int(O,TEXT("militaryReadinessWarningThreshold"),R.MilitaryReadinessWarningThreshold); R.MilitaryReadinessCriticalThreshold=Int(O,TEXT("militaryReadinessCriticalThreshold"),R.MilitaryReadinessCriticalThreshold); R.BorderPressureWarningThreshold=Int(O,TEXT("borderPressureWarningThreshold"),R.BorderPressureWarningThreshold); R.BorderPressureCriticalThreshold=Int(O,TEXT("borderPressureCriticalThreshold"),R.BorderPressureCriticalThreshold); R.TerritorialLossWarningThreshold=Int(O,TEXT("territorialLossWarningThreshold"),R.TerritorialLossWarningThreshold); R.TerritorialLossCriticalThreshold=Int(O,TEXT("territorialLossCriticalThreshold"),R.TerritorialLossCriticalThreshold); R.CurrentInvasionRisk=Int(O,TEXT("currentInvasionRisk"),R.CurrentInvasionRisk); R.InvasionRiskTrigger=Int(O,TEXT("invasionRiskTrigger"),R.InvasionRiskTrigger); R.WarningLevel=Str(O,TEXT("warningLevel"),R.WarningLevel); R.GameOverReason=Str(O,TEXT("gameOverReason"),R.GameOverReason); R.bGameOverOnTakeover=Bool(O,TEXT("gameOverOnTakeover"),R.bGameOverOnTakeover); R.ActiveInvasionCauses=Strs(O,TEXT("activeInvasionCauses")); R.AdvisorWarnings=Strs(O,TEXT("advisorWarnings")); R.RecoveryTips=Strs(O,TEXT("recoveryTips")); return R; }    FDemocracyAdvisorReport ParseReport(const TSharedPtr<FJsonObject>& O){ FDemocracyAdvisorReport R; R.AdvisorName=Str(O,TEXT("advisorName"),R.AdvisorName); R.Category=Str(O,TEXT("category"),R.Category); R.IssueReport=Str(O,TEXT("issueReport"),R.IssueReport); R.Recommendation=Str(O,TEXT("recommendation"),R.Recommendation); R.Warning=Str(O,TEXT("warning"),R.Warning); R.TradeoffExplanation=Str(O,TEXT("tradeoffExplanation"),R.TradeoffExplanation); R.GuidanceLevel=Str(O,TEXT("guidanceLevel"),R.GuidanceLevel); R.Severity=Int(O,TEXT("severity"),R.Severity); return R; }
